"""Feedback-loop stress test. The labels this model learns from are GENERATED by the
inspections it allocates: if you only inspect what a prior model flagged, you only get
labels there, the places you stop visiting look artificially clean, and the model can
go blind to them -- worst in areas where it already has weak signal (lower-income ZIPs).

This tests the README/FAIRNESS mitigation ("keep a baseline of routine inspections
everywhere") instead of just asserting it. Three training regimes, all tested on the
SAME held-out 2025+ set, recall broken out by ZIP income quartile:

  A  representative  -- train on ALL routine <=2024            (the ideal)
  B  pure targeting  -- train only on rows a 2023 model flagged top-40% (censored labels)
  C  targeting+base  -- B's rows PLUS a random 15% baseline of the rest (the mitigation)

If B collapses low-income recall and C restores it, the mitigation is doing real work."""
import pandas as pd, numpy as np, json, os
from sklearn.preprocessing import OrdinalEncoder
from sklearn.ensemble import HistGradientBoostingClassifier
from sklearn.metrics import roc_auc_score

df=pd.read_csv("data/sd_inspections.csv",low_memory=False)
df["completed_date"]=pd.to_datetime(df["completed_date"],errors="coerce")
df["opened_date"]=pd.to_datetime(df["opened_date"],errors="coerce")
df["score"]=pd.to_numeric(df["score"],errors="coerce")
df=df.dropna(subset=["completed_date"]).sort_values(["business_id","completed_date"])
df["major"]=(df["n_major"]>0).astype(int)
df.loc[df["insp_type"].astype(str)!="Routine","score"]=np.nan
g=df.groupby("business_id",sort=False)
df["prior_n"]=g.cumcount()
df["days_since_last"]=(df["completed_date"]-g["completed_date"].shift(1)).dt.days
df["last_score"]=g["score"].transform(lambda s:s.shift().ffill())
df["last_major"]=(g["n_major"].shift(1)>0).astype("float")
df["prior_major_rate"]=g["major"].transform(lambda s:s.shift().expanding().mean())
df["prior_mean_score"]=g["score"].transform(lambda s:s.shift().expanding().mean())
df["prior_mean_viol"]=g["n_violations"].transform(lambda s:s.shift().expanding().mean())
df["facility_age_yrs"]=(df["completed_date"]-df["opened_date"]).dt.days/365.25
df["month"]=df["completed_date"].dt.month
d=df[df["insp_type"].astype(str)=="Routine"].copy().reset_index(drop=True)
d["zip5"]=d["zip"].astype(str).str.extract(r"(\d{5})")[0]

cat=["business_type","zip"]; num=["prior_n","days_since_last","last_score","last_major",
    "prior_major_rate","prior_mean_score","prior_mean_viol","facility_age_yrs","month"]
for c in cat:
    d[c]=d[c].astype("string").fillna("NA")
    if d[c].nunique()>250:
        keep=d[c].value_counts().head(240).index; d[c]=d[c].where(d[c].isin(keep),"OTHER")
y=d["major"].values

def fit_predict(tr_idx, te_mask):
    enc=OrdinalEncoder(handle_unknown="use_encoded_value",unknown_value=-1,encoded_missing_value=-1)
    X=d[cat+num].copy(); enc.fit(X.iloc[tr_idx][cat]); X[cat]=enc.transform(X[cat])
    ci=[X.columns.get_loc(c) for c in cat]
    clf=HistGradientBoostingClassifier(max_iter=300,learning_rate=0.08,max_leaf_nodes=48,
        categorical_features=ci,l2_regularization=1.0,early_stopping=True,n_iter_no_change=20,random_state=0)
    clf.fit(X.iloc[tr_idx],y[tr_idx])
    return clf.predict_proba(X[te_mask])[:,1]

pre  =(d["completed_date"]<="2024-12-31").values
te   =(d["completed_date"]> "2024-12-31").values
y2023=(d["completed_date"]<="2023-12-31").values
in2024=((d["completed_date"]>"2023-12-31")&(d["completed_date"]<="2024-12-31")).values

# selection model: what a 2023-trained model would have flagged in 2024 (the "who gets inspected")
sel_p=pd.Series(np.nan,index=d.index); sel_p[in2024]=fit_predict(np.where(y2023)[0], in2024)
thr=np.nanquantile(sel_p[in2024],0.60)                     # "inspect" the top 40% of 2024
rng=np.random.default_rng(0)
idx_pre=np.where(pre)[0]
idx_2023=np.where(y2023)[0]
flagged_2024=np.where(in2024 & (sel_p>=thr).values)[0]     # censored: only these 2024 labels survive
dropped_2024=np.where(in2024 & (sel_p< thr).values)[0]
baseline=rng.choice(dropped_2024,int(0.15*len(dropped_2024)),replace=False)  # 15% random rescue

arms={"A representative (all <=2024)":idx_pre,
      "B pure targeting (censored)":np.concatenate([idx_2023,flagged_2024]),
      "C targeting + 15% baseline":np.concatenate([idx_2023,flagged_2024,baseline])}

# income by ZIP (reuse fairness cache; skip income breakout if absent)
inc={}
if os.path.exists("acs_cache.json"):
    inc=json.load(open("acs_cache.json")).get("inc",{})
d["income"]=d["zip5"].map(inc)
tt=d[te].copy()
q=pd.qcut(tt["income"],4,labels=["Q1 low","Q2","Q3","Q4 high"]) if tt["income"].notna().any() else None

print(f"2024 labels kept under targeting: {len(flagged_2024)}/{in2024.sum()} "
      f"(+{len(baseline)} random baseline in arm C)\n")
print(f"{'regime':32s} {'train_n':>8s} {'test_AUC':>9s}   recall of criticals by income quartile")
for name,tr_idx in arms.items():
    p=fit_predict(tr_idx, te)
    auc=roc_auc_score(y[te],p)
    thr20=np.quantile(p,0.80); flag=(p>=thr20).astype(int)
    line=f"{name:32s} {len(tr_idx):8,d} {auc:9.3f}   "
    if q is not None:
        r=pd.DataFrame({"grp":q.values,"major":y[te],"flag":flag})
        rec=r[r["major"]==1].groupby("grp",observed=True)["flag"].mean()*100
        line+="  ".join(f"{g.split()[0]}:{rec.get(g,np.nan):4.0f}%" for g in ["Q1 low","Q2","Q3","Q4 high"])
    print(line)
print("\nRead: a big drop in B's Q1(low-income) recall vs A would mean targeting is going blind")
print("to low-signal areas, and C pulling it back would show the baseline safeguard working.")
print("LIMIT: this is ONE round of censoring (2024 labels only) with full pre-2023 history kept;")
print("real feedback compounds over many cycles, so a small effect here is reassuring, not a")
print("clean bill of health -- recall-by-group still has to be monitored live after deployment.")
